/**
 * Protection catalog – the single source of truth for
 *   1. validating / clamping the per-server configuration (backend),
 *   2. rendering the settings forms (dashboard fetches it via /api/meta/catalog),
 *   3. the Lua schema of the FiveM resource (generated by `npm run gen:lua-schema`).
 *
 * To add a protection: add an entry here, run `npm run gen:lua-schema`, implement the
 * handler in resource/fxshield/server/. The dashboard picks it up automatically.
 */

export const CONFIG_VERSION = 1

export interface IntField {
  type: 'int'
  key: string
  label: string
  help?: string
  unit?: string
  min: number
  max: number
  default: number
}
export interface BoolField {
  type: 'bool'
  key: string
  label: string
  help?: string
  default: boolean
}
export interface SelectField {
  type: 'select'
  key: string
  label: string
  help?: string
  options: { value: string; label: string }[]
  default: string
}
export interface TextField {
  type: 'text'
  key: string
  label: string
  help?: string
  maxLength: number
  default: string
}
export type Field = IntField | BoolField | SelectField | TextField
export type FieldValue = number | boolean | string

export interface ModeDef {
  value: string
  label: string
  description: string
}

export type ProtectionGroup = 'connections' | 'ingame'

export interface ProtectionDef {
  id: string
  group: ProtectionGroup
  title: string
  summary: string
  /** Shown as a badge: the protection needs OneSync to work. */
  requiresOneSync?: boolean
  /** Honest warning shown in the dashboard (side effects, limits). */
  caveat?: string
  modes: ModeDef[]
  defaultMode: string
  fields: Field[]
}

export interface Config {
  v: number
  general: Record<string, FieldValue>
  /** per protection: `mode` + its fields */
  protections: Record<string, Record<string, FieldValue>>
  messages: Record<string, string>
}

// ───────────────────────────── field helpers ─────────────────────────────

const int = (
  key: string,
  label: string,
  min: number,
  max: number,
  def: number,
  extra: { unit?: string; help?: string } = {},
): IntField => ({ type: 'int', key, label, min, max, default: def, ...extra })

const bool = (key: string, label: string, def: boolean, help?: string): BoolField => ({
  type: 'bool',
  key,
  label,
  default: def,
  ...(help ? { help } : {}),
})

const select = (
  key: string,
  label: string,
  options: [string, string][],
  def: string,
  help?: string,
): SelectField => ({
  type: 'select',
  key,
  label,
  options: options.map(([value, lbl]) => ({ value, label: lbl })),
  default: def,
  ...(help ? { help } : {}),
})

const text = (key: string, label: string, maxLength: number, def: string, help?: string): TextField => ({
  type: 'text',
  key,
  label,
  maxLength,
  default: def,
  ...(help ? { help } : {}),
})

