// ───────────────────────────── normalisation ─────────────────────────────

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v)
}

/* eslint-disable no-control-regex */
const CONTROL_CHARS = /[\u0000-\u001f\u007f]/g

export function normalizeField(def: Field, value: unknown): FieldValue {
  switch (def.type) {
    case 'int': {
      const n = typeof value === 'number' ? value : typeof value === 'string' && value.trim() !== '' ? Number(value) : NaN
      if (!Number.isFinite(n)) return def.default
      return Math.min(def.max, Math.max(def.min, Math.round(n)))
    }
    case 'bool':
      return typeof value === 'boolean' ? value : def.default
    case 'select':
      return typeof value === 'string' && def.options.some((o) => o.value === value) ? value : def.default
    case 'text': {
      if (typeof value !== 'string') return def.default
      const s = value.replace(CONTROL_CHARS, ' ').trim().slice(0, def.maxLength)
      return s === '' ? def.default : s
    }
  }
}

export function normalizeConfig(input: unknown): Config {
  const raw = isPlainObject(input) ? input : {}
  const rawGeneral = isPlainObject(raw.general) ? raw.general : {}
  const rawProtections = isPlainObject(raw.protections) ? raw.protections : {}
  const rawMessages = isPlainObject(raw.messages) ? raw.messages : {}

  const general: Record<string, FieldValue> = {}
  for (const f of GENERAL_FIELDS) general[f.key] = normalizeField(f, rawGeneral[f.key])

  const protections: Record<string, Record<string, FieldValue>> = {}
  for (const def of PROTECTIONS) {
    const rp = isPlainObject(rawProtections[def.id]) ? (rawProtections[def.id] as Record<string, unknown>) : {}
    const out: Record<string, FieldValue> = {}
    out.mode = typeof rp.mode === 'string' && def.modes.some((m) => m.value === rp.mode) ? rp.mode : def.defaultMode
    for (const f of def.fields) out[f.key] = normalizeField(f, rp[f.key])
    protections[def.id] = out
  }

  const messages: Record<string, string> = {}
  for (const f of MESSAGE_FIELDS) messages[f.key] = normalizeField(f, rawMessages[f.key]) as string

  return { v: CONFIG_VERSION, general, protections, messages }
}

export function defaultConfig(): Config {
  return normalizeConfig({})
}

/** Deep-merge `patch` (partial config) onto `base`, then normalise. */
export function mergeConfig(base: Config, patch: unknown): Config {
  const p = isPlainObject(patch) ? patch : {}
  const pProt = isPlainObject(p.protections) ? p.protections : {}
  const merged = {
    general: { ...base.general, ...(isPlainObject(p.general) ? p.general : {}) },
    protections: Object.fromEntries(
      PROTECTIONS.map((d) => [d.id, { ...base.protections[d.id], ...(isPlainObject(pProt[d.id]) ? (pProt[d.id] as object) : {}) }]),
    ),
    messages: { ...base.messages, ...(isPlainObject(p.messages) ? p.messages : {}) },
  }
  return normalizeConfig(merged)
}

export function presetConfig(id: string): Config | null {
  const preset = PRESETS.find((p) => p.id === id)
  if (!preset) return null
  const base = defaultConfig()
  // presets only change protections, never general settings or messages
  return mergeConfig(base, { protections: preset.overrides })
}

/** JSON-serialisable catalog for the dashboard. */
export function catalogForClient() {
  return {
    version: CONFIG_VERSION,
    general: GENERAL_FIELDS,
    messages: MESSAGE_FIELDS,
    protections: PROTECTIONS,
    presets: PRESETS.map((p) => ({ id: p.id, name: p.name, description: p.description, config: presetConfig(p.id) })),
    defaults: defaultConfig(),
  }
}
